use xiom.io;

type Person = {
  name: Str;
  age: Int;
}

fn create_person(name: Str, age: Int) -> Person {
  return Person{ name: name, age: age };
}

fn older_person(a: Person, b: Person) -> Person {
  if a.age > b.age {
    return a;
  }
  return b;
}

fn main() -> Int {
  let p1 = create_person("Ivy", 14);
  let p2 = create_person("Jack", 19);
  let older = older_person(p1, p2);
  io.println(older.name.to_str());
  return 0;
}
